func refMatch(route, req string) (bool, [][2]string) {
	rs := strings.Split(route, "/")
	qs := strings.Split(req, "/")
	hasCatch := len(rs) > 0 && strings.HasPrefix(rs[len(rs)-1], "*")
	if len(rs) != len(qs) {
		if !hasCatch || len(qs) < len(rs)-1 {
			return false, nil
		}
	}
	var params [][2]string
	for i := 1; i < len(rs); i++ {
		seg := rs[i]
		if strings.HasPrefix(seg, "*") {
			if i > len(qs) {
				return false, nil
			}
			val := "/" + strings.Join(qs[i:], "/")
			params = append(params, [2]string{seg[1:], val})
			return true, params
		}
		if i >= len(qs) {
			return false, nil
		}
		if strings.HasPrefix(seg, ":") {
			params = append(params, [2]string{seg[1:], qs[i]})
			continue
		}
		if seg != qs[i] {
			return false, nil
		}
	}
	if len(qs) != len(rs) {
		return false, nil
	}
	return true, params
}

