// parse a route into segments of parts; catchAll handled separately
func parse(route string) (segs [][]part, catchAll string, ok bool) {
	raw := strings.Split(route, "/")
	for i := 1; i < len(raw); i++ {
		s := raw[i]
		if strings.HasPrefix(s, "*") {
			if i != len(raw)-1 {
				return nil, "", false
			}
			catchAll = s[1:]
			if catchAll == "" {
				return nil, "", false
			}
			return segs, catchAll, true
		}
		var ps []part
		cur := ""
		for _, ch := range s {
			if ch == ':' {
				if cur != "" {
					ps = append(ps, part{lit: cur})
					cur = ""
				}
				ps = append(ps, part{param: "\x00"})
				continue
			}
			if len(ps) > 0 && ps[len(ps)-1].param != "" && cur == "" {
				// param already open, name continues
				ps[len(ps)-1].param += string(ch)
				continue
			}
			cur += string(ch)
		}
		if cur != "" {
			ps = append(ps, part{lit: cur})
		}
		// fix param names
		for j := range ps {
			if ps[j].param != "" {
				ps[j].param = strings.TrimPrefix(ps[j].param, "\x00")
			}
		}
		segs = append(segs, ps)
	}
	return segs, "", true
}

func refMatch(route, req string) (bool, [][2]string) {
	segs, catchAll, ok := parse(route)
	if !ok {
		return false, nil
	}
	qs := strings.Split(req, "/")[1:]
	var params [][2]string
	for i, ps := range segs {
		if i >= len(qs) {
			return false, nil
		}
		q := qs[i]
		for _, p := range ps {
			if p.param != "" {
				params = append(params, [2]string{p.param, q})
				q = ""
				continue
			}
			if !strings.HasPrefix(q, p.lit) {
				return false, nil
			}
			q = q[len(p.lit):]
		}
		if q != "" {
			return false, nil
		}
	}
	if catchAll != "" {
		if len(qs) < len(segs) {
			return false, nil
		}
		params = append(params, [2]string{catchAll, "/" + strings.Join(qs[len(segs):], "/")})
		return true, params
	}
	if len(qs) != len(segs) {
		return false, nil
	}
	return true, params
}

