func ciCandidates(routes []string, p string, fixSlash bool) map[string]bool {
	res := map[string]bool{}
	add := func(s string) { res[s] = true }
	for _, r := range routes {
		if o, ok := ciMatch(r, p); ok {
			add(o)
		}
		if fixSlash {
			if strings.HasSuffix(p, "/") && len(p) > 1 {
				if o, ok := ciMatch(r, p[:len(p)-1]); ok {
					add(o)
				}
			} else if !strings.HasSuffix(p, "/") {
				if o, ok := ciMatch(r, p+"/"); ok {
					add(o)
				}
			}
		}
	}
	return res
}

