package gin

import (
	"fmt"
	"strings"
	"testing"
)

func wildcardNamesInvalid(path string) (bad []string) {
	// for each ':' or '*', the name runs until '/' or end
	for i := 0; i < len(path); i++ {
		c := path[i]
		if c != ':' && c != '*' {
			continue
		}
		end := i + 1
		for end < len(path) && path[end] != '/' {
			end++
		}
		name := path[i+1 : end]
		if name == "" {
			bad = append(bad, fmt.Sprintf("empty name at %d (%q)", i, path))
		}
		if strings.ContainsAny(name, ":*") {
			bad = append(bad, fmt.Sprintf("multi wildcard at %d (%q)", i, path))
		}
	}
	return
}

func TestBruteWildcard(t *testing.T) {
	alpha := []byte{'/', ':', '*', 'a'}
	var gen func(prefix string, depth int)
	var viol []string
	var unexpected []string
	gen = func(prefix string, depth int) {
		if depth == 0 {
			p := prefix
			if !strings.HasPrefix(p, "/") {
				return
			}
			invalid := wildcardNamesInvalid(p)
			recv := catchPanic(func() {
				tree := &node{}
				tree.addRoute(p, fakeHandler(p))
			})
			if len(invalid) > 0 && recv == nil {
