			if len(invalid) == 0 && recv != nil {
				// may still panic for other reasons (catch-all not at end / no / before catch-all)
				msg := fmt.Sprint(recv)
				if !strings.Contains(msg, "catch-all") && !strings.Contains(msg, "no / before catch-all") {
					unexpected = append(unexpected, fmt.Sprintf("%q panic=%v", p, recv))
				}
			}
			return
		}
		for _, c := range alpha {
			gen(prefix+string(c), depth-1)
		}
	}
	for d := 1; d <= 7; d++ {
		gen("", d)
	}
	fmt.Println("violations (accepted but empty/invalid wildcard name):", len(viol))
	for i, v := range viol {
		if i < 40 {
			fmt.Println("  ", v)
		}
	}
	fmt.Println("unexpected panics on valid paths:", len(unexpected))
	for i, v := range unexpected {
		if i < 40 {
			fmt.Println("  ", v)
		}
	}
}
